import { test, expect } from '@playwright/test';
import * as ui from '../support/ui';

test.setTimeout(240_000);
test.describe("sorting", () => {
  test("sorting", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-10");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00"})).toBe(true);
    const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C"}));
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "ada", "grade": "A"}));
    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B"}));
    const p_dot = ui.must(await ui.addPerson(pg_uma, {"name": "Dot", "grade": "A"}));
    const c_ben_0 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "10.00"}));
    const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "30.00"}));
    const c_dot_0 = ui.must(await ui.addClaim(pg_uma, p_dot, {"amount": "30.00"}));
    expect(await ui.claimAction(pg_uma, c_ben_0, "open")).toBe(true);
    expect(await ui.claimAction(pg_uma, c_ada_0, "open")).toBe(true);
    expect(await ui.claimAction(pg_uma, c_dot_0, "open")).toBe(true);
    expect(await ui.personOrder(pg_uma)).toEqual([p_cam, p_ada, p_ben, p_dot]);
    await ui.sortBy(pg_uma, "name");
    expect(await ui.personOrder(pg_uma)).toEqual([p_ada, p_ben, p_cam, p_dot]);
    await ui.sortBy(pg_uma, "grade");
    expect(await ui.personOrder(pg_uma)).toEqual([p_ada, p_dot, p_ben, p_cam]);
    await ui.sortBy(pg_uma, "due-total");
    expect(await ui.personOrder(pg_uma)).toEqual([p_ben, p_ada, p_dot, p_cam]);
    expect(await ui.hold(pg_uma, p_dot, {"from": "2026-03-01"})).toBe(true);
    expect(await ui.personOrder(pg_uma)).toEqual([p_dot, p_ben, p_ada, p_cam]);
    await ui.setSetting(pg_uma, "cap", "1.50");
    expect(await ui.personOrder(pg_uma)).toEqual([p_dot, p_ada, p_ben, p_cam]);
    await ui.setSetting(pg_uma, "cap", "");
    const pg_vic = await ui.userPage(browser, "vic", sheet);
    expect(await ui.personOrder(pg_vic)).toEqual([p_cam, p_ada, p_ben, p_dot]);
    await ui.refresh(pg_uma);
    expect(await ui.personOrder(pg_uma)).toEqual([p_dot, p_ben, p_ada, p_cam]);
    expect(await ui.bulkOpen(pg_uma, [c_ada_0])).toEqual({ opened: 0, refused: 1 });
    await ui.sortBy(pg_uma, "added");
    expect(await ui.personOrder(pg_uma)).toEqual([p_cam, p_ada, p_ben, p_dot]);
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "20.00"})).toBe(true);
    expect(await ui.editPerson(pg_uma, p_cam, {"grade": "A"})).toBe(true);
    await ui.sortBy(pg_uma, "grade");
    expect(await ui.personOrder(pg_uma)).toEqual([p_cam, p_ada, p_dot, p_ben]);
    await ui.refresh(pg_uma);
    await expect(pg_uma.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("0.00");
    await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("6.00");
    await expect(pg_uma.getByTestId("person-row-" + p_dot).getByTestId("person-due-total")).toHaveText("0.00");
    await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-due-total")).toHaveText("2.00");
    await expect(pg_uma.getByTestId("rollup-claimed-total")).toHaveText("40.00");
    await expect(pg_uma.getByTestId("rollup-due-total")).toHaveText("2.00");
    await expect(pg_uma.getByTestId("rollup-overdue-count")).toHaveText("0");
    await expect(pg_uma.getByTestId("rollup-overdue-total")).toHaveText("0.00");
    await expect(pg_uma.getByTestId("rollup-settled-total")).toHaveText("0.00");
    await expect(pg_uma.getByTestId("rollup-open-total")).toHaveText("8.00");
    await expect(pg_uma.getByTestId("bulk-settle-batch")).toHaveText("");
    await expect(pg_uma.getByTestId("rollup-cut-total")).toHaveText("0.00");
    await ui.expectAudit(sheet, [
      `RATE_SET sheet=${sheet} by=uma grade=A rate=10.00`,
      `RATE_SET sheet=${sheet} by=uma grade=B rate=20.00`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Cam grade=C`,
      `ROLLUP sheet=${sheet} by=uma person=Cam claimed=0.00 due-total=n/a overdue-total=0.00`,
      `PERSON_ADDED sheet=${sheet} by=uma name=ada grade=A`,
      `ROLLUP sheet=${sheet} by=uma person=ada claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Ben grade=B`,
      `ROLLUP sheet=${sheet} by=uma person=Ben claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `PERSON_ADDED sheet=${sheet} by=uma name=Dot grade=A`,
      `ROLLUP sheet=${sheet} by=uma person=Dot claimed=0.00 due-total=0.00 overdue-total=0.00`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Ben amount=10.00 date=2026-03-10`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=ada amount=30.00 date=2026-03-10`,
      `CLAIM_ADDED sheet=${sheet} by=uma person=Dot amount=30.00 date=2026-03-10`,
      `CLAIM_OPENED sheet=${sheet} by=uma person=Ben amount=10.00 date=2026-03-10 number=1`,
